import asyncio
async def t(svc, op, params=None, region="us-east-1"):
    try:
        r = await call_boto3(service_name=svc, operation_name=op, region_name=region, params=params or {})
        return {"call":svc+"."+op,"ok":True,"r":r}
    except Exception as e:
        return {"call":svc+"."+op,"ok":False,"e":str(e)[:300]}

res = await asyncio.gather(
    t("route53","ListHostedZones"),
    t("acm","ListCertificates"),
    t("ec2","DescribeSubnets",{"Filters":[{"Name":"default-for-az","Values":["true"]}]}),
    t("ec2","DescribeSecurityGroups",{"Filters":[{"Name":"group-name","Values":["default"]}]}),
    t("iam","ListInstanceProfiles"),
    t("ssm","GetParameter",{"Name":"/aws/service/ami-amazon-linux-latest/al2023-ami-kernel-default-x86_64"}),
    t("elbv2","DescribeLoadBalancers"),
    t("ec2","DescribeInstances",{"Filters":[{"Name":"instance-state-name","Values":["running","pending"]}]}),
    return_exceptions=True)

out=[]
for x in res:
    if not isinstance(x, dict):
        out.append(str(x)[:200]); continue
    c=x["call"]
    if not x["ok"]: out.append({c:x["e"]}); continue
    r=x["r"]
    if c=="route53.ListHostedZones": out.append({c:[z["Name"] for z in r.get("HostedZones",[])]})
    elif c=="acm.ListCertificates": out.append({c:[(a.get("DomainName"),a.get("Status")) for a in r.get("CertificateSummaryList",[])]})
    elif c=="ec2.DescribeSubnets": out.append({c:[(s["SubnetId"],s["AvailabilityZone"],s["VpcId"]) for s in r["Subnets"]]})
    elif c=="ec2.DescribeSecurityGroups": out.append({c:[(s["GroupId"],s["VpcId"]) for s in r["SecurityGroups"]]})
    elif c=="iam.ListInstanceProfiles": out.append({c:[p["InstanceProfileName"] for p in r["InstanceProfiles"]]})
    elif c=="ssm.GetParameter": out.append({c:r["Parameter"]["Value"]})
    elif c=="elbv2.DescribeLoadBalancers": out.append({c:[(l["LoadBalancerName"],l["DNSName"]) for l in r["LoadBalancers"]]})
    elif c=="ec2.DescribeInstances": out.append({c:[(i["InstanceId"],i["State"]["Name"]) for res2 in r["Reservations"] for i in res2["Instances"]]})
result = out
result

